//! # Sortformer diarization cross-check against a pretrained ONNX reference.
//!
//! Validates [`bunsen`]'s Sortformer implementation against an independent
//! one, generated by `burn_onnx::ModelGen` from `altunenes/parakeet-rs`'s
//! export of NVIDIA's `Nemotron-3-Diarization`: one streaming step, with the
//! speaker cache kept by the caller, as `NeMo`'s own export keeps it.
//!
//! ## This crate hosts nothing, and generates nothing
//!
//! The generated reference comes from `bunsen-bundled-sortformer`'s
//! `onnx_gen` feature, which fetches the export, pins it to a SHA-256,
//! rewrites the two constructs `burn-onnx` cannot import, and caches it, all
//! under the **`download`** feature, which is off by default so an ordinary
//! `cargo build --workspace` never reaches the network.
//!
//! ```sh
//! cargo test --release -p sortformer-model-validation \
//!   --features download,gpu-tests,wgpu
//! ```
//!
//! `gpu-tests` compiles every test that loads a model, `download` fetches
//! what they compare against, and a backend feature says what they run on.
//! None is inferred from the others. Without both `download` and `gpu-tests`
//! the suite is the fixture-integrity checks, which load no model.
//!
//! `SORTFORMER_ONNX_NEMOTRON`, `SORTFORMER_NEMOTRON_SAFETENSORS` and
//! `SORTFORMER_NEMOTRON_CONFIG` point the build at local files instead; they
//! are read by `bunsen-bundled-sortformer`'s build script, not this crate's.
//!
//! ## The reference is itself checked
//!
//! `testdata/onnx_reference.json` records what onnxruntime, the export's own
//! runtime, computes for the published graph on deterministic synthetic input
//! (`tools/gen_sortformer_fixtures.py` writes it). The `reference` tests hold
//! the generated model to it, so neither a defect in the ONNX import nor one
//! in the rewrite can pass for a defect in bunsen, or hide one.

#![cfg_attr(not(feature = "download"), allow(unused))]

use bunsen::support::testing::TensorRecord;
use burn::prelude::*;
use serde::Deserialize;

/// The reference model, generated from the `parakeet-rs` export.
#[cfg(feature = "download")]
pub mod reference {
    pub use bunsen_bundled_sortformer::onnx_gen::*;
}

#[cfg(all(test, feature = "download", feature = "gpu-tests"))]
mod reference_tests;

#[cfg(all(test, feature = "download", feature = "gpu-tests"))]
mod staged;

#[cfg(all(test, feature = "download", feature = "gpu-tests"))]
mod speech;

#[cfg(all(test, feature = "download", feature = "gpu-tests"))]
mod asr;

#[cfg(all(test, feature = "download"))]
mod v2_checkpoints;

/// The mel channel count of `Nemotron-3-Diarization`.
pub const N_MELS: usize = 128;

/// The pre-encode embedding width: what the speaker cache and FIFO hold.
pub const D_ENC: usize = 512;

/// The speakers `Nemotron-3-Diarization` tells apart.
pub const N_SPEAKERS: usize = 8;

/// Mel frames per 80 ms frame, and 10 ms frames per 80 ms frame.
pub const SUBSAMPLING: usize = 8;

/// The fixture onnxruntime wrote: see the crate docs.
pub fn onnx_reference() -> OnnxReference {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/testdata/onnx_reference.json");
    let text = std::fs::read_to_string(path).expect("read the onnx reference fixture");
    serde_json::from_str(&text).expect("parse the onnx reference fixture")
}

/// `testdata/onnx_reference.json`.
#[derive(Debug, Deserialize)]
pub struct OnnxReference {
    /// The export and revision the fixture was made from.
    pub source: String,

    /// The runtime that computed it.
    pub runtime: String,

    /// The Nemotron streaming step, at each geometry.
    pub nemotron: Vec<StepRecord>,

    /// The v2.1 export and revision.
    pub v2_1_source: String,

    /// The v2.1 streaming step, at each geometry.
    pub v2_1: Vec<V21StepRecord>,
}

/// The v2.1 speakers: 4.
pub const V2_N_SPEAKERS: usize = 4;

/// One v2.1 streaming step on synthetic input.
#[derive(Debug, Deserialize)]
pub struct V21StepRecord {
    /// The chunk's length, in mel frames.
    pub mel_frames: usize,

    /// The speaker cache's allocated frames.
    pub spkcache_frames: usize,

    /// The speaker cache's valid frames.
    pub spkcache_valid: usize,

    /// The FIFO's allocated frames.
    pub fifo_frames: usize,

    /// The FIFO's valid frames.
    pub fifo_valid: usize,

    /// `spkcache_fifo_chunk_preds [1, C+F+T/8, 4]`, the 80 ms predictions.
    pub preds: TensorRecord,

    /// `chunk_pre_encode_embs [1, T/8, 512]`.
    pub chunk_pre_encode_embs: TensorRecord,

    /// `chunk_pre_encode_lengths [1]`.
    pub chunk_pre_encode_lengths: Vec<i64>,
}

impl V21StepRecord {
    /// The 80 ms frames the predictions cover, as allocated.
    pub fn output_frames(&self) -> usize {
        self.spkcache_frames + self.fifo_frames + self.mel_frames.div_ceil(SUBSAMPLING)
    }
}

/// One streaming step on synthetic input.
#[derive(Debug, Deserialize)]
pub struct StepRecord {
    /// The chunk's length, in mel frames.
    pub mel_frames: usize,

    /// The speaker cache's allocated frames.
    pub spkcache_frames: usize,

    /// The speaker cache's valid frames.
    pub spkcache_valid: usize,

    /// The FIFO's allocated frames.
    pub fifo_frames: usize,

    /// The FIFO's valid frames.
    pub fifo_valid: usize,

    /// `preds_diar [1, C+F+T/8, 8]`, the 80 ms predictions.
    pub preds_diar: TensorRecord,

    /// `preds_hires [1, 8*(C+F+T/8), 8]`, the 10 ms predictions.
    pub preds_hires: TensorRecord,

    /// `chunk_pre_encode_embs [1, T/8, 512]`.
    pub chunk_pre_encode_embs: TensorRecord,

    /// `chunk_pre_encode_lengths [1]`.
    pub chunk_pre_encode_lengths: Vec<i64>,
}

impl StepRecord {
    /// The 80 ms frames the predictions cover: the cache's, the FIFO's and
    /// the chunk's, as allocated.
    pub fn output_frames(&self) -> usize {
        self.spkcache_frames + self.fifo_frames + self.mel_frames.div_ceil(SUBSAMPLING)
    }
}

/// A deterministic `[1, frames, N_MELS]` stand-in for log-mel features: a
/// tonal pattern that moves through time, and a ramp of noise. The formula
/// `tools/gen_sortformer_fixtures.py` uses.
pub fn synthetic_chunk(
    frames: usize,
    device: &Device,
) -> Tensor<3> {
    use std::f64::consts::PI;
    let data: Vec<f32> = (0..frames * N_MELS)
        .map(|k| {
            let (t, f) = ((k / N_MELS) as f64, (k % N_MELS) as f64);
            let noise = ((t * 31.0 + f * 17.0) % 97.0) / 48.5 - 1.0;
            (3.0 * (2.0 * PI * (f / 16.0 + t / 30.0)).sin() + 0.3 * noise) as f32
        })
        .collect();
    Tensor::from_data(TensorData::new(data, [1, frames, N_MELS]), device)
}

/// A deterministic `[1, frames, D_ENC]` stand-in for pre-encode embeddings;
/// `salt` varies it.
pub fn synthetic_embeddings(
    frames: usize,
    salt: usize,
    device: &Device,
) -> Tensor<3> {
    use std::f64::consts::PI;
    let salt = salt as f64;
    let data: Vec<f32> = (0..frames * D_ENC)
        .map(|k| {
            let (r, c) = ((k / D_ENC) as f64, (k % D_ENC) as f64);
            let noise = ((r * 13.0 + c * 7.0 + salt * 29.0) % 89.0) / 44.5 - 1.0;
            (2.0 * (2.0 * PI * (c / 37.0 + r / 11.0 + salt / 5.0)).sin() + 0.5 * noise) as f32
        })
        .collect();
    Tensor::from_data(TensorData::new(data, [1, frames, D_ENC]), device)
}

/// A length, as the graph takes it: `[1]`, `i64` (the graph's own constants
/// are `i64`, and a backend's default integer may not be).
pub fn graph_length(
    value: usize,
    device: &Device,
) -> Tensor<1, Int> {
    Tensor::from_data(
        TensorData::from([value as i64]),
        (device, burn::tensor::DType::I64),
    )
}

/// `testdata/ami_reference.json`: `NeMo`'s own diarization of
/// `bunsen-test-audio`'s AMI excerpt (`tools/gen_sortformer_ami_fixture.py`).
#[derive(Debug, Deserialize)]
pub struct AmiReference {
    /// The checkpoint the reference ran.
    pub source: String,

    /// The clip.
    pub clip: String,

    /// Per latency preset.
    pub presets: std::collections::BTreeMap<String, AmiPreset>,
}

/// `NeMo`'s run of one preset.
#[derive(Debug, Deserialize)]
pub struct AmiPreset {
    /// The 10 ms speaker probabilities, `[1, frames, 8]`.
    pub probs: TensorRecord,

    /// md-eval's scores of the unfiltered turns against the RTTM, collar
    /// 0.25 s, overlap scored.
    pub der: DerRecord,
}

/// A diarization error rate and its parts, as fractions of the scored
/// reference speech.
#[derive(Debug, Deserialize)]
pub struct DerRecord {
    /// The error rate.
    pub der: f64,

    /// Speaker confusion.
    pub confusion: f64,

    /// False alarm.
    pub false_alarm: f64,

    /// Missed speech.
    pub missed: f64,
}

/// The fixture `NeMo` wrote: see [`AmiReference`].
pub fn ami_reference() -> AmiReference {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/testdata/ami_reference.json");
    let text = std::fs::read_to_string(path).expect("read the AMI reference fixture");
    serde_json::from_str(&text).expect("parse the AMI reference fixture")
}

/// The pretrained cache the checkpoint comes through.
///
/// Under `download`, it is rooted at `bunsen-bundled-sortformer`'s directory,
/// which its build laid out as one, and offline: nothing is fetched at run
/// time. Routing the checkpoint through the library's own factory is also
/// what this crate is validating.
#[cfg(feature = "download")]
pub fn weights_cache() -> bunsen::data::pretrained::PretrainedCache {
    cache_at(bunsen_bundled_sortformer::cache_dir())
}

/// An offline pretrained cache rooted at a bundled crate's directory.
#[cfg(feature = "download")]
pub fn cache_at(dir: &std::path::Path) -> bunsen::data::pretrained::PretrainedCache {
    use bunsen::data::pretrained::{
        PretrainedCache,
        PretrainedCacheOptions,
    };
    let options = PretrainedCacheOptions::default()
        .with_disk(
            bunsen::data::cache::BunsenDiskCacheOptions::default()
                .with_cache_dir(Some(dir.to_path_buf())),
        )
        .with_offline(true);
    PretrainedCache::new(options).expect("open the pretrained cache")
}

/// `Nemotron-3-Diarization`, through bunsen's factory and [`weights_cache`].
#[cfg(feature = "download")]
pub fn load_bundle(
    device: &Device
) -> std::sync::Arc<bunsen::kits::speech::sortformer::SortformerBundle> {
    bunsen::kits::speech::sortformer::pretrained::default_sortformer_factory()
        .expect("the sortformer factory")
        .load_bundle("nvidia/nemotron-3-diarization", &weights_cache(), device)
        .unwrap_or_else(|e| panic!("load Nemotron-3-Diarization: {e}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The fixture is what the crate docs say it is, and covers the
    /// geometries the reference tests run; no model is needed.
    #[test]
    fn test_fixture_is_well_formed() {
        let fixture = onnx_reference();
        assert!(fixture.source.starts_with("altunenes/parakeet-rs@4d2a8bc7"));
        assert_eq!(fixture.nemotron.len(), 2);
        for step in &fixture.nemotron {
            let frames = step.output_frames();
            assert_eq!(step.preds_diar.shape, [1, frames, N_SPEAKERS]);
            assert_eq!(
                step.preds_hires.shape,
                [1, SUBSAMPLING * frames, N_SPEAKERS]
            );
            let te = step.mel_frames.div_ceil(SUBSAMPLING);
            assert_eq!(step.chunk_pre_encode_embs.shape, [1, te, D_ENC]);
            assert_eq!(step.chunk_pre_encode_lengths, [te as i64]);
            for record in [
                &step.preds_diar,
                &step.preds_hires,
                &step.chunk_pre_encode_embs,
            ] {
                assert_eq!(record.samples.len(), record.expected_samples());
            }
            // Probabilities.
            assert!(
                step.preds_hires
                    .samples
                    .iter()
                    .all(|p| (0.0..=1.0).contains(p))
            );
            assert!(step.preds_hires.samples.iter().any(|&p| p > 0.5));
        }
    }

    /// The v2.1 records cover the Nemotron geometries and a first step,
    /// with an empty cache and FIFO.
    #[test]
    fn test_v2_1_fixture_is_well_formed() {
        let fixture = onnx_reference();
        assert!(fixture.v2_1_source.starts_with("Scrybl/"));
        assert!(fixture.v2_1_source.contains("3be92087"));
        assert_eq!(fixture.v2_1.len(), 3);
        assert!(
            fixture
                .v2_1
                .iter()
                .any(|s| s.spkcache_frames == 0 && s.fifo_frames == 0)
        );
        for step in &fixture.v2_1 {
            assert_eq!(step.preds.shape, [1, step.output_frames(), V2_N_SPEAKERS]);
            let te = step.mel_frames.div_ceil(SUBSAMPLING);
            assert_eq!(step.chunk_pre_encode_embs.shape, [1, te, D_ENC]);
            assert_eq!(step.chunk_pre_encode_lengths, [te as i64]);
            for record in [&step.preds, &step.chunk_pre_encode_embs] {
                assert_eq!(record.samples.len(), record.expected_samples());
            }
            assert!(step.preds.samples.iter().all(|p| (0.0..=1.0).contains(p)));
        }
    }

    /// The AMI reference covers the presets the speech tests run, at the
    /// clip's 6000 frames of 10 ms.
    #[test]
    fn test_ami_reference_is_well_formed() {
        let fixture = ami_reference();
        assert!(fixture.source.contains("f667ed73"));
        assert_eq!(fixture.clip, "ami_en2002d_2132.wav");
        for name in ["low_latency", "offline"] {
            let preset = &fixture.presets[name];
            assert_eq!(preset.probs.shape, [1, 6000, N_SPEAKERS]);
            assert_eq!(preset.probs.samples.len(), preset.probs.expected_samples());
            assert!((0.0..1.0).contains(&preset.der.der));
        }
    }

    /// The synthetic inputs have the shapes the fixture was made with.
    #[test]
    fn test_synthetic_inputs() {
        let device = bunsen::support::testing::cpu_device();
        assert_eq!(synthetic_chunk(16, &device).dims(), [1, 16, N_MELS]);
        assert_eq!(synthetic_embeddings(3, 1, &device).dims(), [1, 3, D_ENC]);
        let v: Vec<i64> = graph_length(7, &device)
            .into_data()
            .try_to_vec::<i64>()
            .unwrap();
        assert_eq!(v, [7]);
    }
}
